#include <builtin_MATH.h>
/* RTDS-style C draft using scalar-expanded Schur elimination.
   No runtime matrix objects are required on this codegen path. */
enum { RETAINED_NODES = 4, INTERNAL_NODES = 2 };

STATIC:

    double G11 = 0.0;
    double G12 = 0.0;
    double G22 = 0.0;
    double Gc = 0.0;
    double IhisC1 = 0.0;
    double IhisC2 = 0.0;
    double Ihis_p = 0.0;
    double Ihis_s = 0.0;
    double scalar_shared_inv_den_0 = 0.0;
    double scalar_shared_inv_den_1 = 0.0;
    double scalar_shared_inv_den_2 = 0.0;
    double scalar_code_tmp0 = 0.0;
    double scalar_code_tmp1 = 0.0;
    double scalar_code_tmp2 = 0.0;
    double scalar_code_tmp3 = 0.0;
    double scalar_code_tmp4 = 0.0;
    double scalar_code_tmp5 = 0.0;
    double scalar_t1t2_tmp0 = 0.0;
    double scalar_t1t2_tmp1 = 0.0;
    double scalar_t1t2_tmp2 = 0.0;
    double scalar_t1t2_tmp3 = 0.0;
    double scalar_t1t2_tmp4 = 0.0;
    double scalar_t1t2_tmp5 = 0.0;
    double scalar_t1t2_tmp6 = 0.0;
    double scalar_t1t2_tmp7 = 0.0;
    double scalar_t1t2_tmp8 = 0.0;

LOCAL_STATIC:

    double scalar_ram_tmp0 = 0.0;
    double scalar_ram_tmp1 = 0.0;
    double scalar_ram_tmp2 = 0.0;
    double scalar_ram_tmp3 = 0.0;
    double scalar_ram_tmp4 = 0.0;
    double scalar_ram_tmp5 = 0.0;
    double scalar_ram_tmp6 = 0.0;
    double scalar_ram_tmp7 = 0.0;
    double scalar_ram_tmp8 = 0.0;
    double scalar_ram_tmp9 = 0.0;
    double scalar_ram_tmp10 = 0.0;
    double scalar_ram_tmp11 = 0.0;
    double scalar_ram_tmp12 = 0.0;
    double scalar_ram_tmp13 = 0.0;
    double scalar_ram_tmp14 = 0.0;
    double scalar_ram_tmp15 = 0.0;
    double scalar_ram_tmp16 = 0.0;

RAM_PASS1:

    int row;
    int col;


    /* Scalar-expanded RAM-side G stamp. */
    g_mat_nods[0] = getNodeNum(comp, "N1");
    g_mat_nods[1] = getNodeNum(comp, "N2");
    g_mat_nods[2] = getNodeNum(comp, "N3");
    g_mat_nods[3] = getNodeNum(comp, "N4");
    for (row = 0; row < 4; row++) {
        for (col = 0; col < 4; col++) {
            g_mat_over[row][col] = 0.0;
        }
    }
    scalar_shared_inv_den_0 = 1.0/(G11 + Gc);
    scalar_shared_inv_den_1 = 1.0/(-pow(G12, 2.0)/(G11 + Gc) + G22 + Gc);
    scalar_shared_inv_den_2 = 1.0/(G11*G22 + G11*Gc - pow(G12, 2.0) + G22*Gc + pow(Gc, 2.0));
    scalar_ram_tmp0 = -Gc;
    scalar_ram_tmp1 = pow(Gc, 2.0);
    scalar_ram_tmp2 = scalar_ram_tmp1*scalar_shared_inv_den_0;
    scalar_ram_tmp3 = pow(G12, 2.0);
    scalar_ram_tmp4 = scalar_ram_tmp1*scalar_shared_inv_den_1;
    scalar_ram_tmp5 = G11*scalar_shared_inv_den_0;
    scalar_ram_tmp6 = G12*Gc*scalar_shared_inv_den_0;
    scalar_ram_tmp7 = G12*scalar_ram_tmp5 - G12;
    scalar_ram_tmp8 = scalar_ram_tmp7*scalar_shared_inv_den_1;
    scalar_ram_tmp9 = -Gc*scalar_ram_tmp5 - scalar_ram_tmp6*scalar_ram_tmp8;
    scalar_ram_tmp10 = G12*scalar_ram_tmp2*scalar_shared_inv_den_1;
    scalar_ram_tmp11 = -G22 + scalar_ram_tmp3*scalar_shared_inv_den_0;
    scalar_ram_tmp12 = scalar_ram_tmp11*scalar_shared_inv_den_1;
    scalar_ram_tmp13 = -scalar_ram_tmp12*scalar_ram_tmp6 - scalar_ram_tmp6;
    scalar_ram_tmp14 = Gc*scalar_ram_tmp8;
    scalar_ram_tmp15 = -scalar_ram_tmp11*scalar_ram_tmp8 - scalar_ram_tmp7;
    scalar_ram_tmp16 = Gc*scalar_ram_tmp12;
    g_mat_over[0][0] = -scalar_ram_tmp0 - scalar_ram_tmp2 - scalar_ram_tmp3*scalar_ram_tmp4/pow(G11 + Gc, 2.0);
    g_mat_over[0][1] = scalar_ram_tmp9;
    g_mat_over[0][2] = scalar_ram_tmp10;
    g_mat_over[0][3] = scalar_ram_tmp13;
    g_mat_over[1][0] = scalar_ram_tmp9;
    g_mat_over[1][1] = -pow(G11, 2.0)*scalar_shared_inv_den_0 + G11 - pow(scalar_ram_tmp7, 2.0)*scalar_shared_inv_den_1;
    g_mat_over[1][2] = scalar_ram_tmp14;
    g_mat_over[1][3] = scalar_ram_tmp15;
    g_mat_over[2][0] = scalar_ram_tmp10;
    g_mat_over[2][1] = scalar_ram_tmp14;
    g_mat_over[2][2] = -scalar_ram_tmp0 - scalar_ram_tmp4;
    g_mat_over[2][3] = scalar_ram_tmp16;
    g_mat_over[3][0] = scalar_ram_tmp13;
    g_mat_over[3][1] = scalar_ram_tmp15;
    g_mat_over[3][2] = scalar_ram_tmp16;
    g_mat_over[3][3] = -pow(scalar_ram_tmp11, 2.0)*scalar_shared_inv_den_1 - scalar_ram_tmp11;
    setupGMatrix(4);

CODE:

BEGIN_T0:

    /* CODE-side scalar assignments from scalar-expanded Schur formulas. */
    scalar_code_tmp0 = -IhisC1 + Ihis_p;
    scalar_code_tmp1 = scalar_code_tmp0*scalar_shared_inv_den_0;
    scalar_code_tmp2 = G12*scalar_shared_inv_den_0;
    scalar_code_tmp3 = -G12*scalar_code_tmp1 + Ihis_s;
    scalar_code_tmp4 = scalar_shared_inv_den_1*(IhisC2 + scalar_code_tmp3);
    scalar_code_tmp5 = Gc*scalar_code_tmp4;
    InjN1 = Gc*scalar_code_tmp1 + IhisC1 - scalar_code_tmp2*scalar_code_tmp5;
    InjN2 = G11*scalar_code_tmp0*scalar_shared_inv_den_0 - Ihis_p - scalar_code_tmp4*(G11*scalar_code_tmp2 - G12);
    InjN3 = -IhisC2 + scalar_code_tmp5;
    InjN4 = -scalar_code_tmp3 - scalar_code_tmp4*(pow(G12, 2.0)*scalar_shared_inv_den_0 - G22);

T1_T2:

    /* Scalar-expanded internal-node voltage recovery after retained voltages are available. */
    scalar_t1t2_tmp0 = pow(Gc, 2.0);
    scalar_t1t2_tmp1 = G22*Gc;
    scalar_t1t2_tmp2 = N1*scalar_shared_inv_den_2;
    scalar_t1t2_tmp3 = G11*Gc;
    scalar_t1t2_tmp4 = G11*G22 - pow(G12, 2.0);
    scalar_t1t2_tmp5 = N2*scalar_shared_inv_den_2;
    scalar_t1t2_tmp6 = N4*scalar_shared_inv_den_2;
    scalar_t1t2_tmp7 = G12*Gc;
    scalar_t1t2_tmp8 = N3*scalar_shared_inv_den_2;
    inner_left = scalar_shared_inv_den_2*(G12*IhisC2 + G12*Ihis_s + G22*IhisC1 - G22*Ihis_p + Gc*IhisC1 - Gc*Ihis_p) + scalar_t1t2_tmp2*(scalar_t1t2_tmp0 + scalar_t1t2_tmp1) + scalar_t1t2_tmp5*(scalar_t1t2_tmp3 + scalar_t1t2_tmp4) + scalar_t1t2_tmp6*scalar_t1t2_tmp7 - scalar_t1t2_tmp7*scalar_t1t2_tmp8;
    inner_right = scalar_shared_inv_den_2*(-G11*IhisC2 - G11*Ihis_s - G12*IhisC1 + G12*Ihis_p - Gc*IhisC2 - Gc*Ihis_s) - scalar_t1t2_tmp2*scalar_t1t2_tmp7 + scalar_t1t2_tmp5*scalar_t1t2_tmp7 + scalar_t1t2_tmp6*(scalar_t1t2_tmp1 + scalar_t1t2_tmp4) + scalar_t1t2_tmp8*(scalar_t1t2_tmp0 + scalar_t1t2_tmp3);

#include <matrixLIB.h>
#include <builtin_MATH.h>
/* RTDS-style C draft for structured node elimination.
   RAM math reference may use matrix_Add/Sub/Mul on raw arrays.
   Runtime sections use MATRIX_ matrixDim/register/condition plus set_CODE,
   matrix_mult_CODE, matrix_matXvec_CODE, matrix_add_CODE/subtract_CODE,
   matrix_scalarMult_CODE, MATH_matx_invert,
   mat_2x2_sym_inv_code, mat_3x3_sym_inv_code. */
enum { RETAINED_NODES = 4, INTERNAL_NODES = 2 };
/* Dimension names:
 * RETAINED_NODES is the number of external nodes kept in the reduced network.
 * INTERNAL_NODES is the number of eliminated internal nodes used by Schur/Vk recovery.
 */

/* RTDS lifecycle placement generated from final-expression dependency analysis.
   RAM_PASS1 stamps only RAM_CONSTANT Gred entries through g_mat_over.
   CODE/BEGIN_T0 computes only dynamic reduced-G and non-direct Ihisred paths.
   T1_T2 reads solved node voltages and recovers eliminated-node voltages when needed. */
STATIC:

    /* Runtime matrix objects */
    MATRIX_ Grk_code = {0};
    MATRIX_ Gkr_code = {0};
    MATRIX_ Gkk_code = {0};
    MATRIX_ W_code = {0};
    MATRIX_ Ihisr_code = {0};
    MATRIX_ Ihisk_code = {0};
    MATRIX_ Ihisred_code = {0};
    MATRIX_ Vr_code = {0};
    MATRIX_ Vk_code = {0};
    MATRIX_ tmp_Grk_W_code = {0};
    MATRIX_ tmp_Grk_W_Ihisk_code = {0};
    MATRIX_ tmp_W_Gkr_code = {0};
    MATRIX_ tmp_W_Gkr_Vr_code = {0};
    MATRIX_ tmp_W_Ihisk_code = {0};
    MATRIX_ tmp_Vk_sum_code = {0};
    /* Runtime state */
    int rtds_matrix_code_ready = 0;
    /* User G/CODE symbols */
    double G11 = 0.0;
    double G12 = 0.0;
    double G22 = 0.0;
    double Gc = 0.0;
    /* User Ihis/history symbols */
    double IhisC1 = 0.0;
    double IhisC2 = 0.0;
    double Ihis_p = 0.0;
    double Ihis_s = 0.0;
    /* Block-matrix scalar aliases */
    double Gkk_inner_left_inner_left = 0.0;
    double Gkk_inner_right_inner_right = 0.0;
    double Gkk_shared_1 = 0.0;
    double Gkr_inner_left_N2 = 0.0;
    double Gkr_inner_right_N4 = 0.0;
    double Gkr_shared_1 = 0.0;
    double Gkr_shared_2 = 0.0;
    double Grk_N2_inner_left = 0.0;
    double Grk_N4_inner_right = 0.0;
    double Grk_shared_1 = 0.0;
    double Grk_shared_2 = 0.0;

LOCAL_STATIC:

    /* RAM G stamp scalar aliases */
    double ramG_N3_N3 = 0.0;
    double ramG_N4_N4 = 0.0;
    double sourceG_tmp0 = 0.0;
    double sourceG_tmp1 = 0.0;
    double sourceG_tmp10 = 0.0;
    double sourceG_tmp11 = 0.0;
    double sourceG_tmp12 = 0.0;
    double sourceG_tmp13 = 0.0;
    double sourceG_tmp14 = 0.0;
    double sourceG_tmp15 = 0.0;
    double sourceG_tmp2 = 0.0;
    double sourceG_tmp3 = 0.0;
    double sourceG_tmp4 = 0.0;
    double sourceG_tmp5 = 0.0;
    double sourceG_tmp6 = 0.0;
    double sourceG_tmp7 = 0.0;
    double sourceG_tmp8 = 0.0;
    double sourceG_tmp9 = 0.0;

RAM_PASS1:

    int row;
    int col;


    int err = 0;
    /* ************************************************************************
     * RAM-SIDE G MATRIX VALUE SETUP
     * Assign or compute every G-related value before any RAM-side use.
     * This section stamps only fixed g_mat_over entries; CODE-owned matrices are refreshed in CODE.
     * ************************************************************************ */



    g_mat_nods[0] = getNodeNum(comp, "N1");
    g_mat_nods[1] = getNodeNum(comp, "N2");
    g_mat_nods[2] = getNodeNum(comp, "N3");
    g_mat_nods[3] = getNodeNum(comp, "N4");
    /* g_mat_over is provided by the PSYS/CBuilder runtime; initialize, do not define it here. */
    for (row = 0; row < 4; row++) {
        for (col = 0; col < 4; col++) {
            g_mat_over[row][col] = 0.0;
        }
    }
    /* Repeated source-level subexpressions for this generated block. */
    sourceG_tmp0 = 1.0/(G11*G22 + G11*Gc - pow(G12, 2.0) + G22*Gc + pow(Gc, 2.0));
    sourceG_tmp1 = 1.0/(-pow(G12, 2.0) + (G11 + Gc)*(G22 + Gc));
    sourceG_tmp2 = 1.0/(pow(G12, 2.0) - (G11 + Gc)*(G22 + Gc));
    sourceG_tmp3 = pow(G12, 2.0);
    sourceG_tmp4 = G11*G22 - sourceG_tmp3;
    sourceG_tmp5 = G11*Gc + sourceG_tmp4;
    sourceG_tmp6 = Gc*sourceG_tmp0*sourceG_tmp5;
    sourceG_tmp7 = -Gc*sourceG_tmp0*sourceG_tmp5;
    sourceG_tmp8 = pow(Gc, 2.0);
    sourceG_tmp9 = G12*sourceG_tmp8;
    sourceG_tmp10 = sourceG_tmp1*sourceG_tmp9;
    sourceG_tmp11 = -sourceG_tmp0*sourceG_tmp9;
    sourceG_tmp12 = sourceG_tmp2*sourceG_tmp9;
    sourceG_tmp13 = sourceG_tmp0*sourceG_tmp9;
    sourceG_tmp14 = G11 + Gc;
    sourceG_tmp15 = Gc*sourceG_tmp1*(-G22*sourceG_tmp14 + sourceG_tmp3);
    /* ramG_N3_N3 represents Gred[N3,N3]: sourceG_tmp1*(Gc*(sourceG_tmp14*(G22 + Gc) - sourceG_tmp3) - sourceG_tmp14*sourceG_tmp8). */
    ramG_N3_N3 = sourceG_tmp1*(Gc*(sourceG_tmp14*(G22 + Gc) - sourceG_tmp3) - sourceG_tmp14*sourceG_tmp8);
    /* ramG_N4_N4 represents Gred[N4,N4]: Gc*sourceG_tmp0*(G22*Gc + sourceG_tmp4). */
    ramG_N4_N4 = Gc*sourceG_tmp0*(G22*Gc + sourceG_tmp4);
    g_mat_over[0][0] = sourceG_tmp6;
    g_mat_over[0][1] = sourceG_tmp7;
    g_mat_over[0][2] = sourceG_tmp10;
    g_mat_over[0][3] = sourceG_tmp11;
    g_mat_over[1][0] = sourceG_tmp7;
    g_mat_over[1][1] = sourceG_tmp6;
    g_mat_over[1][2] = sourceG_tmp12;
    g_mat_over[1][3] = sourceG_tmp13;
    g_mat_over[2][0] = sourceG_tmp10;
    g_mat_over[2][1] = sourceG_tmp12;
    g_mat_over[2][2] = ramG_N3_N3;
    g_mat_over[2][3] = sourceG_tmp15;
    g_mat_over[3][0] = sourceG_tmp11;
    g_mat_over[3][1] = sourceG_tmp13;
    g_mat_over[3][2] = sourceG_tmp15;
    g_mat_over[3][3] = ramG_N4_N4;
    setupGMatrix(4);

    err += matrixDim(&Grk_code, RETAINED_NODES, INTERNAL_NODES);
    err += matrixDim(&Gkr_code, INTERNAL_NODES, RETAINED_NODES);
    err += matrixDim(&Gkk_code, INTERNAL_NODES, INTERNAL_NODES);
    err += matrixDim(&W_code, INTERNAL_NODES, INTERNAL_NODES);
    err += matrixDim(&Ihisr_code, RETAINED_NODES, 1);
    err += matrixDim(&Ihisk_code, INTERNAL_NODES, 1);
    err += matrixDim(&Ihisred_code, RETAINED_NODES, 1);
    err += matrixDim(&Vr_code, RETAINED_NODES, 1);
    err += matrixDim(&Vk_code, INTERNAL_NODES, 1);
    err += matrixDim(&tmp_Grk_W_code, RETAINED_NODES, INTERNAL_NODES);
    err += matrixDim(&tmp_Grk_W_Ihisk_code, RETAINED_NODES, 1);
    err += matrixDim(&tmp_W_Gkr_code, INTERNAL_NODES, RETAINED_NODES);
    err += matrixDim(&tmp_W_Gkr_Vr_code, INTERNAL_NODES, 1);
    err += matrixDim(&tmp_W_Ihisk_code, INTERNAL_NODES, 1);
    err += matrixDim(&tmp_Vk_sum_code, INTERNAL_NODES, 1);
    if (err > 0) {
        reportError_RW("network_node", STOP_IMMEDIATELY_CONDITION,
                       "RTDS matrix allocation failed for component %s.", Name);
    }
    matrix_register(&Grk_code);
    matrix_register(&Gkr_code);
    matrix_register(&Gkk_code);
    matrix_register(&W_code);
    matrix_register(&Ihisr_code);
    matrix_register(&Ihisk_code);
    matrix_register(&Vr_code);
    matrix_register(&Ihisred_code);
    matrix_register(&Vk_code);
    matrix_register(&tmp_W_Gkr_code);
    matrix_register(&tmp_Grk_W_code);
    matrix_register(&tmp_W_Gkr_Vr_code);
    matrix_register(&tmp_Grk_W_Ihisk_code);
    matrix_register(&tmp_W_Ihisk_code);
    matrix_register(&tmp_Vk_sum_code);

CODE:

BEGIN_T0:

    if (!rtds_matrix_code_ready) {
        initializeMatricesForCode();
        conditionMatrixForCODE(&Grk_code);
        conditionMatrixForCODE(&Gkr_code);
        conditionMatrixForCODE(&Gkk_code);
        conditionMatrixForCODE(&W_code);
        conditionMatrixForCODE(&Ihisr_code);
        conditionMatrixForCODE(&Ihisk_code);
        conditionMatrixForCODE(&Vr_code);
        conditionMatrixForCODE(&Ihisred_code);
        conditionMatrixForCODE(&Vk_code);
        conditionMatrixForCODE(&tmp_W_Gkr_code);
        conditionMatrixForCODE(&tmp_Grk_W_code);
        conditionMatrixForCODE(&tmp_W_Gkr_Vr_code);
        conditionMatrixForCODE(&tmp_Grk_W_Ihisk_code);
        conditionMatrixForCODE(&tmp_W_Ihisk_code);
        conditionMatrixForCODE(&tmp_Vk_sum_code);
        rtds_matrix_code_ready = 1;
    }


    /* ************************************************************************
     * CODE-SIDE G MATRIX VALUE SETUP
     * Update runtime G-related symbols and matrices before the reduction math below.
     * Only matrices required by dynamic G, Ihis reduction, or Vk recovery are refreshed.
     * ************************************************************************ */



    /* Runtime refresh. Use set_CODE for matrices touched in CODE; do not write MATRIX_.p directly. */
    /* Grk_shared_1 represents Grk[N1,inner_left], Grk[N3,inner_right]: -Gc. */
    Grk_shared_1 = -Gc;
    /* Grk_N2_inner_left represents Grk[N2,inner_left]: -G11. */
    Grk_N2_inner_left = -G11;
    /* Grk_shared_2 represents Grk[N2,inner_right], Grk[N4,inner_left]: -G12. */
    Grk_shared_2 = -G12;
    /* Grk_N4_inner_right represents Grk[N4,inner_right]: -G22. */
    Grk_N4_inner_right = -G22;
    /* Gkr_shared_1 represents Gkr[inner_left,N1], Gkr[inner_right,N3]: -Gc. */
    Gkr_shared_1 = -Gc;
    /* Gkr_inner_left_N2 represents Gkr[inner_left,N2]: -G11. */
    Gkr_inner_left_N2 = -G11;
    /* Gkr_shared_2 represents Gkr[inner_left,N4], Gkr[inner_right,N2]: -G12. */
    Gkr_shared_2 = -G12;
    /* Gkr_inner_right_N4 represents Gkr[inner_right,N4]: -G22. */
    Gkr_inner_right_N4 = -G22;
    /* Gkk_inner_left_inner_left represents Gkk[inner_left,inner_left]: G11 + Gc. */
    Gkk_inner_left_inner_left = G11 + Gc;
    /* Gkk_shared_1 represents Gkk[inner_left,inner_right], Gkk[inner_right,inner_left]: G12. */
    Gkk_shared_1 = G12;
    /* Gkk_inner_right_inner_right represents Gkk[inner_right,inner_right]: G22 + Gc. */
    Gkk_inner_right_inner_right = G22 + Gc;
    set_CODE(&Grk_code, 0, 0, Grk_shared_1);
    set_CODE(&Grk_code, 2, 1, Grk_shared_1);
    set_CODE(&Grk_code, 1, 0, Grk_N2_inner_left);
    set_CODE(&Grk_code, 1, 1, Grk_shared_2);
    set_CODE(&Grk_code, 3, 0, Grk_shared_2);
    set_CODE(&Grk_code, 3, 1, Grk_N4_inner_right);
    set_CODE(&Gkr_code, 0, 0, Gkr_shared_1);
    set_CODE(&Gkr_code, 1, 2, Gkr_shared_1);
    set_CODE(&Gkr_code, 0, 1, Gkr_inner_left_N2);
    set_CODE(&Gkr_code, 0, 3, Gkr_shared_2);
    set_CODE(&Gkr_code, 1, 1, Gkr_shared_2);
    set_CODE(&Gkr_code, 1, 3, Gkr_inner_right_N4);
    set_CODE(&Gkk_code, 0, 0, Gkk_inner_left_inner_left);
    set_CODE(&Gkk_code, 0, 1, Gkk_shared_1);
    set_CODE(&Gkk_code, 1, 0, Gkk_shared_1);
    set_CODE(&Gkk_code, 1, 1, Gkk_inner_right_inner_right);
    double W_code_11 = 0.0;
    double W_code_12 = 0.0;
    double W_code_22 = 0.0;
    mat_2x2_sym_inv_code(get_CODE(&Gkk_code, 0, 0), get_CODE(&Gkk_code, 0, 1), get_CODE(&Gkk_code, 1, 1),
                         &W_code_11, &W_code_12, &W_code_22);
    set_CODE(&W_code, 0, 0, W_code_11);
    set_CODE(&W_code, 0, 1, W_code_12);
    set_CODE(&W_code, 1, 0, W_code_12);
    set_CODE(&W_code, 1, 1, W_code_22);

    /* ************************************************************************
     * CODE-SIDE IHIS VALUE SETUP
     * Update runtime Ihis/history-source values before per-step injection math.
     * Only non-direct Ihisred rows are computed through MATRIX_ CODE helpers.
     * ************************************************************************ */



    set_CODE(&Ihisr_code, 0, 0, IhisC1);
    set_CODE(&Ihisr_code, 1, 0, -Ihis_p);
