    case 1:
        multcase_Ihis_C1_A_1 = Ihis_A - Ihis_C;
        multcase_Ihis_C1_B_1 = -Ihis_A + Ihis_B;
        multcase_Ihis_C1_C_1 = -Ihis_B + Ihis_C;
