    }
    switch (case_id) {
    case 0:
        multcase_Ihis_combined_a = IAhis_rc + Ihis_a - Ihis_c + Ihis_exclude_c0;
        multcase_Ihis_combined_b = IBhis_rc - Ihis_a + Ihis_b;
        multcase_Ihis_combined_c = IChis_rc - Ihis_b + Ihis_c + Ihis_exclude_c2;
