    case 2:
        multcase_Ihis_combined_a = IAhis_rc + Ihis_a + Ihis_exclude_c0;
        multcase_Ihis_combined_b = IBhis_rc + Ihis_b;
        multcase_Ihis_combined_c = IChis_rc + Ihis_c + Ihis_exclude_c2;
        break;
    case 3:
        multcase_Ihis_combined_a = IAhis_rc - IChis_rc + Ihis_a + Ihis_exclude_c0;
        multcase_Ihis_combined_b = -IAhis_rc + IBhis_rc + Ihis_b;
        multcase_Ihis_combined_c = -IBhis_rc + IChis_rc + Ihis_c + Ihis_exclude_c2;
