    Gkr_shared_3 = G12;
    /* Gkr_shared_4 represents Gkr[c,G], Gkr[a,G], Gkr[b,G]: -multcase_G_C1_G_a. */
    Gkr_shared_4 = -multcase_G_C1_G_a;
