    set_CODE(&Gkr_code, 3, 1, Gkr_shared_3);
    set_CODE(&Gkr_code, 0, 3, Gkr_shared_4);
    set_CODE(&Gkr_code, 2, 3, Gkr_shared_4);
    set_CODE(&Gkr_code, 3, 3, Gkr_shared_4);
    set_CODE(&Gkr_code, 0, 4, Gkr_c_P);
    set_CODE(&Gkr_code, 0, 5, Gkr_c_N);
    if (retained_profile == PACK_CASE_0) {
        set_CODE(&Gkr_code, 0, 8, Gkr_shared_5);
        set_CODE(&Gkr_code, 2, 6, Gkr_shared_5);
